def-hyp(
    list-partial(
        Type.annotation(@x, X@Topology.ctxt.X),
        Type.annotation(@y, Y@Topology.ctxt.Y),
        Type.annotation(@f, Type.to(X@Topology.ctxt.X, Y@Topology.ctxt.Y)),
        Type.annotation(@τ_X, Set(Set(X@Topology.ctxt.X))),
        Type.annotation(@τ_Y, Set(Set(Y@Topology.ctxt.Y))),
        Type.annotation(@x_0, X@Topology.ctxt.X)
    ),
    Topology.mapLimit(x, x_0, f, y),
    Logic.forall-typed(
        @V,
        Set(Y@Topology.ctxt.Y),
        Logic.implies(
            Set.mem(V, τ_Y),
            Logic.and(
                Set.mem(y, V),
                Logic.exists-typed(
                    @U,
                    Set(X@Topology.ctxt.X),
                    Logic.and(
                        Topology.deletedNeighborhood(U, x_0),
                        Set.subset(
                            Set.fun(f, U),
                            V
                        )
                    )
                )
            )
        )
    )
)

def-hyp(
    list-partial(
        Type.annotation(@f, Type.to(X@Topology.ctxt.X, Y@Topology.ctxt.Y)),
        Type.annotation(@τ_X, Set(Set(X@Topology.ctxt.X))),
        Type.annotation(@τ_Y, Set(Set(Y@Topology.ctxt.Y)))
    ),
    Topology.openMap(f),
    Logic.forall-typed(
        @U,
        Set(X@Topology.ctxt.X),
        Logic.implies(
            Set.mem(U, τ_X),
            Set.mem(
                Set.fun(f, U),
                τ_Y
            )
        )
    )
)

def-hyp(
    list-partial(
        Type.annotation(@f, Type.to(X@Topology.ctxt.X, Y@Topology.ctxt.Y)),
        Type.annotation(@τ_X, Set(Set(X@Topology.ctxt.X))),
        Type.annotation(@τ_Y, Set(Set(Y@Topology.ctxt.Y)))
    ),
    Topology.homeomorphism(f, X@Topology.ctxt.X, Y@Topology.ctxt.Y),
    Logic.and(Logic.and(Topology.continuousMap(f, X@Topology.ctxt.X, Y@Topology.ctxt.Y), Topology.openMap(f)), Set.bijective(f))
)
